pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(bytes32 assertionId, uint256 time, bytes memory ancillaryData) public {
        c.assertionDisputedCallback(assertionId);
        int256 price = c.getPrice(bytes32(0), 0, ancillaryData);
        assertTrue(price == 0);
    }
}
